/* v32.4.68 — one modal footer contract for the entire ERP. */
UI.resetModalFooter=function(label='حفظ البيانات',{danger=false,hideSubmit=false,cancel='إلغاء'}={}){const foot=UIDocument.getElementById('modalFoot');if(!foot)return null;foot.dataset.mode=hideSubmit?'view':'edit';foot.innerHTML=`<button class="btn ${danger?'danger':'primary'}${hideSubmit?' hidden':''}" type="submit" ${hideSubmit?'aria-hidden="true" tabindex="-1"':''}><span id="modalSaveIcon">${icon(danger?'warning':'save','sm')}</span><span id="modalSubmitText">${esc(label||'تأكيد')}</span></button><button class="btn ghost" type="button" data-ui-close-modal="1">${esc(cancel||'إلغاء')}</button>`;const btn=foot.querySelector('[type=submit]');if(btn){btn.style.display=hideSubmit?'none':'inline-flex';btn.disabled=!!hideSubmit}return btn};
UI.ensureModalFooter=function(){const m=UIDocument.getElementById('modal'),f=UIDocument.getElementById('modalForm'),foot=UIDocument.getElementById('modalFoot');if(!m?.classList.contains('show')||!f||!foot)return;const submit=foot.querySelector('button[type="submit"]');if(foot.dataset.mode!=='view'&&f.onsubmit&&submit){submit.classList.remove('hidden');submit.style.display='inline-flex';submit.disabled=false;submit.removeAttribute('aria-hidden');submit.removeAttribute('tabindex')}};
UI.installModalFooterGuard=function(){if(this._modalFooterGuard||!UIDocument.getElementById('modal'))return;this._modalFooterGuard=new MutationObserver(()=>queueMicrotask(()=>this.ensureModalFooter()));this._modalFooterGuard.observe(UIDocument.getElementById('modal'),{attributes:true,attributeFilter:['class']})};
UI.confirmAction=function(title,message,onConfirm,opts: any={}){const m=UIDocument.getElementById('modal'),f=UIDocument.getElementById('modalForm');UIDocument.getElementById('modalTitle').textContent=title;UIDocument.getElementById('modalSubtitle').textContent=opts.subtitle||'راجع تأثير العملية قبل التنفيذ.';UIDocument.getElementById('modalIcon').innerHTML=icon('warning');this.resetModalFooter(opts.label||'تأكيد',{danger:opts.danger!==false,cancel:opts.cancel||'إلغاء'});UIDocument.getElementById('modalBody').innerHTML=`<div class="danger-note">${esc(message)}</div>`;m.classList.add('show');f.noValidate=true;f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('[type=submit]');if(btn?.disabled)return;if(btn)btn.disabled=true;try{await onConfirm();if(UIDocument.getElementById('modal')?.classList.contains('show'))UI.closeModal(true)}catch(err){toast(err.message||'تعذر تنفيذ العملية','error');if(btn)btn.disabled=false}}};
UI.reasonAction=function(title,message,onConfirm){const m=UIDocument.getElementById('modal'),f=UIDocument.getElementById('modalForm');UIDocument.getElementById('modalTitle').textContent=title;UIDocument.getElementById('modalSubtitle').textContent='السبب سيحفظ في سجل المراجعة.';UIDocument.getElementById('modalIcon').innerHTML=icon('warning');this.resetModalFooter('تأكيد',{danger:true});UIDocument.getElementById('modalBody').innerHTML=`<div class="info-note">${esc(message)}</div><div class="field" style="margin-top:12px"><label>السبب</label><textarea name="reason" required minlength="3"></textarea></div>`;m.classList.add('show');f.noValidate=false;f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('[type=submit]');if(btn?.disabled)return;if(btn)btn.disabled=true;try{await onConfirm(S(new FormData(f).get('reason')).trim());UI.closeModal(true)}catch(err){toast(err.message||'تعذر تنفيذ العملية','error');if(btn)btn.disabled=false}}};
UI.previewFontScale=function(value,el){const select=UIDocument.getElementById('setFontScale');if(select)select.value=String(value);UIDocument.querySelectorAll('.font-size-option').forEach(b=>b.classList.toggle('active',b===el));const sample=UIDocument.getElementById('fontSizeLivePreview');if(sample){sample.style.fontSize=`${15*N(value)}px`;sample.textContent=`معاينة الخط — ${Math.round(15*N(value))}px • الحج والعمرة والمحاسبة والعملاء`}};
