/* Settings are presented as real tabs so operators only handle one concern at a time. */
UI.settingsTabId='company';
UI.settingsDirty=false;
UI.settingsSignature=function(){const active=[...UIDocument.querySelectorAll('.settings-grid>.settings-tab-active input,.settings-grid>.settings-tab-active select,.settings-grid>.settings-tab-active textarea')];return JSON.stringify(active.map(x=>[x.id||x.name||x.dataset.prefix||'',x.type==='checkbox'?x.checked:x.value]))};
