const renderCurrentCommercial=UI.renderCurrent.bind(UI);
UI.renderCurrent=function(){renderCurrentCommercial();if(this.current==='settings')this.initSettingsTabs()};
const openPageCommercial=UI.openPage.bind(UI);
UI.openPage=function(page,id='',opts: any={}){if(this.current==='settings'&&page!=='settings'&&this.settingsDirty&&!confirm('توجد تعديلات غير محفوظة في الإعدادات. هل تريد مغادرة الصفحة؟'))return false;if(page!=='settings')this.settingsDirty=false;return openPageCommercial(page,id,opts)};

