UI._pushModalSnapshot=function(s){if(!s)return false;const sig=this.modalSignature(s),top=this._modalStack[this._modalStack.length-1];if(top&&this.modalSignature(top)===sig)return false;this._modalStack.push(s);if(this._modalStack.length>20)this._modalStack.shift();return true};
